import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import './RiverDashboard.css';

// ── S3 CONFIG FROM .ENV ──────────────────────────────────────────────────────
const BUCKET  = process.env.REACT_APP_AWS_STORAGE_BUCKET_NAME_FORECAST || 'aqi-training';
const REGION  = process.env.REACT_APP_AWS_S3_REGION_NAME_BUCKET        || 'ap-south-1';
const S3_CSV  = `https://${BUCKET}.s3.${REGION}.amazonaws.com/hourly_averages/STA_01_MASTER_LOG.csv`;
const POLL_MS = 30_000;

// ── CSV PARSER ───────────────────────────────────────────────────────────────
function parseCSV(text) {
  const lines = text.trim().split('\n').filter(Boolean);
  if (lines.length < 2) return [];
  const headers = lines[0].split(',').map(h => h.trim());
  return lines.slice(1).map(line => {
    const vals = line.split(',').map(v => v.trim());
    return headers.reduce((o, h, i) => { o[h] = vals[i] ?? ''; return o; }, {});
  });
}

// ── SPARKLINE ────────────────────────────────────────────────────────────────
function Sparkline({ values = [], color = '#00c6ff', h = 46, w = 160 }) {
  const nums = values.map(Number).filter(n => !isNaN(n));
  if (nums.length < 2) return null;
  const min  = Math.min(...nums), max = Math.max(...nums), range = max - min || 1;
  const step = w / (nums.length - 1);
  const pts  = nums.map((v, i) => `${i * step},${h - ((v - min) / range) * h}`).join(' ');
  const lx   = (nums.length - 1) * step;
  const ly   = h - ((nums[nums.length - 1] - min) / range) * h;
  const gid  = `sg${color.replace('#', '')}`;
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{ overflow: 'visible' }}>
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%"   stopColor={color} stopOpacity="0.28" />
          <stop offset="100%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>
      <polygon points={`0,${h} ${pts} ${lx},${h}`} fill={`url(#${gid})`} />
      <polyline points={pts} fill="none" stroke={color} strokeWidth="2"
        strokeLinecap="round" strokeLinejoin="round" />
      <circle cx={lx} cy={ly} r="4" fill={color}
        style={{ filter: `drop-shadow(0 0 5px ${color})` }} />
    </svg>
  );
}

// ── WATER LEVEL GAUGE ────────────────────────────────────────────────────────
function WaterGauge({ value, max = 5 }) {
  const pct   = Math.min(100, Math.max(0, (value / max) * 100));
  const color = pct > 80 ? '#ff6b6b' : pct > 50 ? '#ffd43b' : '#00c6ff';
  const label = pct > 80 ? 'HIGH' : pct > 50 ? 'MODERATE' : 'NORMAL';
  return (
    <div className="rdb-gauge-wrap">
      <div className="rdb-gauge-labels">
        <span>0 m</span>
        <span className="rdb-gauge-status" style={{ color }}>{label}</span>
        <span>{max} m</span>
      </div>
      <div className="rdb-gauge-track">
        <div className="rdb-gauge-fill" style={{
          width: `${pct}%`,
          background: `linear-gradient(90deg, ${color}66, ${color})`,
          boxShadow: `0 0 12px ${color}`
        }} />
        {[25, 50, 75].map(t => (
          <div key={t} className="rdb-gauge-tick" style={{ left: `${t}%` }} />
        ))}
      </div>
      <div className="rdb-gauge-pct" style={{ color }}>{pct.toFixed(1)}% of max</div>
    </div>
  );
}

// ── STAT CARD ────────────────────────────────────────────────────────────────
function StatCard({ label, value, unit, delta, color, icon, history }) {
  const dir = delta > 0 ? '▲' : delta < 0 ? '▼' : '─';
  const dc  = delta > 0 ? '#ff6b6b' : delta < 0 ? '#51cf66' : '#5a7a99';
  return (
    <div className="rdb-card" style={{ '--ac': color }}>
      <div className="rdb-card-head">
        <span className="rdb-card-icon">{icon}</span>
        <span className="rdb-card-label">{label}</span>
      </div>
      <div className="rdb-card-value">
        {value ?? '—'}
        <span className="rdb-card-unit"> {unit}</span>
      </div>
      <div className="rdb-card-foot">
        <span style={{ color: dc, fontFamily: 'var(--rdb-mono)', fontSize: '0.7rem' }}>
          {dir} {delta !== 0 ? Math.abs(delta).toFixed(4) : 'stable'}
        </span>
        <Sparkline values={history} color={color} />
      </div>
    </div>
  );
}

// ── MAIN PAGE ────────────────────────────────────────────────────────────────
export default function Riverdata() {
  const navigate = useNavigate();

  const [rows,      setRows]      = useState([]);
  const [status,    setStatus]    = useState('idle');   // idle|loading|ok|error
  const [error,     setError]     = useState(null);
  const [lastFetch, setLastFetch] = useState(null);
  const [countdown, setCountdown] = useState(POLL_MS / 1000);
  const [newIds,    setNewIds]    = useState(new Set());
  const cdRef = useRef(null);

  // ── fetch ──────────────────────────────────────────────────────────────────
  const fetchData = useCallback(async () => {
    setStatus('loading');
    setError(null);
    try {
      const res = await fetch(`${S3_CSV}?_t=${Date.now()}`, { cache: 'no-store' });
      if (!res.ok) throw new Error(`HTTP ${res.status} — ${res.statusText}`);
      const parsed = parseCSV(await res.text());

      setRows(prev => {
        const prevSet = new Set(prev.map(r => r['Update_Timestamp']));
        const fresh   = parsed.filter(r => !prevSet.has(r['Update_Timestamp']));
        if (fresh.length) {
          setNewIds(new Set(fresh.map(r => r['Update_Timestamp'])));
          setTimeout(() => setNewIds(new Set()), 3500);
        }
        return parsed;
      });

      setLastFetch(new Date());
      setStatus('ok');
    } catch (e) {
      setError(e.message);
      setStatus('error');
    }
    setCountdown(POLL_MS / 1000);
  }, []);

  // polling
  useEffect(() => {
    fetchData();
    const t = setInterval(fetchData, POLL_MS);
    return () => clearInterval(t);
  }, [fetchData]);

  // countdown ticker
  useEffect(() => {
    cdRef.current = setInterval(
      () => setCountdown(c => (c > 0 ? c - 1 : POLL_MS / 1000)),
      1000
    );
    return () => clearInterval(cdRef.current);
  }, []);

  // ── derived ────────────────────────────────────────────────────────────────
  const latest = rows[rows.length - 1];
  const prevR  = rows[rows.length - 2];
  const delta  = key => (!latest || !prevR) ? 0
    : parseFloat(latest[key]) - parseFloat(prevR[key]);
  const hist   = key => rows.map(r => parseFloat(r[key])).filter(v => !isNaN(v));

  const SM = {
    idle:    { label: 'Initialising', color: '#778ca3' },
    loading: { label: 'Syncing…',     color: '#ffd43b' },
    ok:      { label: 'Live',         color: '#51cf66' },
    error:   { label: 'Error',        color: '#ff6b6b' },
  }[status];

  const progressPct = ((POLL_MS / 1000 - countdown) / (POLL_MS / 1000)) * 100;

  // ── render ─────────────────────────────────────────────────────────────────
  return (
    <div className="rdb-root">

      {/* ══ TOPBAR ══════════════════════════════════════════════════════════ */}
      <div className="rdb-topbar">
        {/* ← Back to Weather Home */}
        <button className="rdb-back-btn" onClick={() => navigate('/weather-home')}>
          <span className="rdb-back-arrow">←</span>
          Weather Home
        </button>

        {/* Title */}
        <div className="rdb-topbar-center">
          <span className="rdb-wave-icon">〰</span>
          <div>
            <h1 className="rdb-title">PERIYAR RIVER · STA_01</h1>
            <p className="rdb-subtitle">Real-Time Water Level Monitor</p>
          </div>
        </div>

        {/* Status */}
        <div className="rdb-topbar-right">
          <div className="rdb-live-badge" style={{ '--sc': SM.color }}>
            <span className="rdb-live-dot" />
            <span className="rdb-live-label">{SM.label}</span>
          </div>
          <button className="rdb-refresh-btn" onClick={fetchData} title="Refresh now">↻</button>
        </div>
      </div>

      {/* ══ SYNC BAR ════════════════════════════════════════════════════════ */}
      {status === 'ok' && (
        <div className="rdb-syncbar">
          <div className="rdb-syncbar-fill" style={{ width: `${progressPct}%` }} />
          <span className="rdb-syncbar-label">Auto-refresh in {countdown}s</span>
        </div>
      )}

      {/* ══ ERROR ═══════════════════════════════════════════════════════════ */}
      {error && (
        <div className="rdb-error-banner">
          ⚠&nbsp;{error}
          <span className="rdb-error-hint">
            {' '}— Add this origin to your S3 bucket CORS policy.
          </span>
        </div>
      )}

      {/* ══ STAT CARDS ══════════════════════════════════════════════════════ */}
      <div className="rdb-cards-grid">
        <StatCard
          label="Water Level" icon="🌊" unit="m" color="#00c6ff"
          value={latest ? parseFloat(latest['WL(m)']).toFixed(4) : null}
          delta={delta('WL(m)')} history={hist('WL(m)')}
        />
        <StatCard
          label="Altitude" icon="⛰" unit="m" color="#ffd43b"
          value={latest ? parseFloat(latest['ALT(m)']).toFixed(4) : null}
          delta={delta('ALT(m)')} history={hist('ALT(m)')}
        />
        <StatCard
          label="Longitude" icon="📍" unit="°D" color="#cc5de8"
          value={latest ? parseFloat(latest['LON(D)']).toFixed(6) : null}
          delta={delta('LON(D)')} history={hist('LON(D)')}
        />
        <StatCard
          label="Hour Averaged" icon="🕐" unit="" color="#51cf66"
          value={latest ? latest['Hour_Averaged'] : null}
          delta={0} history={[]}
        />
      </div>

      {/* ══ WATER LEVEL GAUGE ═══════════════════════════════════════════════ */}
      {latest && (
        <div className="rdb-gauge-section">
          <div className="rdb-section-card">
            <div className="rdb-section-header">
              <span className="rdb-section-title">🌊 Live Water Level Gauge</span>
              <span className="rdb-section-val">
                {parseFloat(latest['WL(m)']).toFixed(4)} m
              </span>
            </div>
            <WaterGauge value={parseFloat(latest['WL(m)'])} max={5} />
            <div className="rdb-gauge-meta">
              <span>Last reading: <strong>{latest['Update_Timestamp']}</strong></span>
              {lastFetch && (
                <span>
                  Fetched: {lastFetch.toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata' })}
                </span>
              )}
            </div>
          </div>
        </div>
      )}

      {/* ══ DATA TABLE ══════════════════════════════════════════════════════ */}
      <div className="rdb-table-section">
        <div className="rdb-table-topbar">
          <h2 className="rdb-table-title">Station Log Records</h2>
          <div className="rdb-table-badges">
            <span className="rdb-badge">{rows.length} rows</span>
            <span className="rdb-badge rdb-badge--cyan">30 s auto-refresh</span>
            <span className="rdb-badge rdb-badge--muted">{BUCKET} · {REGION}</span>
          </div>
        </div>

        <div className="rdb-table-scroll">
          {rows.length === 0 ? (
            <div className="rdb-empty">
              {status === 'loading'
                ? <><span className="rdb-spinner">⟳</span> Fetching data from S3…</>
                : 'No records found in the CSV.'}
            </div>
          ) : (
            <table className="rdb-table">
              <thead>
                <tr>
                  <th>#</th>
                  <th>Update Timestamp</th>
                  <th>LON (D)</th>
                  <th>ALT (m)</th>
                  <th>WL (m)</th>
                  <th>Hour Averaged</th>
                </tr>
              </thead>
              <tbody>
                {[...rows].reverse().map((row, i) => {
                  const isNew    = newIds.has(row['Update_Timestamp']);
                  const isLatest = i === 0;
                  return (
                    <tr
                      key={row['Update_Timestamp'] + i}
                      className={[
                        isNew    ? 'rdb-tr-new'    : '',
                        isLatest ? 'rdb-tr-latest' : '',
                      ].join(' ')}
                    >
                      <td className="rdb-td-num">{rows.length - i}</td>
                      <td className="rdb-td-ts">{row['Update_Timestamp']}</td>
                      <td>{parseFloat(row['LON(D)']).toFixed(6)}</td>
                      <td>{parseFloat(row['ALT(m)']).toFixed(4)}</td>
                      <td>
                        <span className="rdb-wl-pill">
                          {parseFloat(row['WL(m)']).toFixed(4)}
                        </span>
                      </td>
                      <td>{row['Hour_Averaged']}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* ══ FOOTER ══════════════════════════════════════════════════════════ */}
      <div className="rdb-footer">
        <span>S3 · {BUCKET} · {REGION}</span>
        {lastFetch && (
          <span>
            Last synced:{' '}
            {lastFetch.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })}
          </span>
        )}
        <button className="rdb-footer-home-btn" onClick={() => navigate('/weather-home')}>
          ← Weather Home
        </button>
      </div>

    </div>
  );
}
